#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_transfer_allocation_export_retains_native_before_metadata_and_physical_output(){
 publish();let from=ArtifactDialect::from(dialect());let sqlite=ArtifactDialect::from(SQLITE_SNAPSHOT);let route=io_route(&from,&sqlite,1).await.unwrap().value;
 for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let grant=snapshot_grant();let mut receive=|_:NativeDecodeProgress|true;let mut emit=|_:NativeEncodeProgress|true;let mut receive_recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut emit_recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut receive_control=NativeDecodeControl::new(limits().max_allocation_bytes,&mut receive);let mut emit_control=NativeEncodeControl::new(limits().max_allocation_bytes,&mut emit);receive_control.install_retirement_recipient(&mut receive_recipient).unwrap();emit_control.install_retirement_recipient(&mut emit_recipient).unwrap();let mut native=IoRunControl::new(&mut receive_control,&mut emit_control,grant);
  let payload=input(encoding);let mut yes=|_|true;let mut direct=SqliteSnapshotControl::new(&mut yes,limits());let domain=export(&payload,&mut direct,&mut native.snapshot_decode().unwrap()).unwrap().value;let used=limits().max_allocation_bytes-direct.allocation_remaining_bytes();assert_eq!(domain.table("transfer_literal").unwrap().single_row().unwrap().text(1).unwrap(),neutral()["literal"].as_str().unwrap());
  let mut stages=Vec::new();let file=run(&route,payload.clone(),limits(),&mut|progress|{stages.push(progress.phase);true},&mut native).await.unwrap().value;let IoPayload::Binary(bytes)=file else{panic!("SQLite endpoint must return binary")};independent(&bytes);assert!(bytes.len()>used);
  for phase in [SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::WritePages]{assert!(stages.contains(&phase));assert!(run(&route,payload.clone(),limits(),&mut|progress|progress.phase!=phase,&mut native).await.is_err());}
  assert!(run(&route,payload,SqliteDatabaseLimits{max_allocation_bytes:used,..limits()},&mut|_|true,&mut native).await.is_err(),"typed native and relational backing exhaust the allowance before metadata and SQLite pages may allocate");
 }
 let payload=input(SnapshotEncoding::Text);let mut yes=|_|true;let grant=snapshot_grant();let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(0,&mut yes);native.install_retirement_recipient(&mut recipient).unwrap();let mut checkpoint=|_|true;let mut snapshot=SqliteSnapshotControl::new(&mut checkpoint,limits());let(before,after)=(native.owned_bytes(),snapshot.allocation_remaining_bytes());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||<TransferSnapshot as store::ArtifactSqliteSnapshot>::decode_sqlite_snapshot_native(&payload,&mut snapshot,&mut store::NativeSnapshotDecodeOwner::new(&mut native,grant)));assert!(result.is_err());assert_eq!((native.owned_bytes(),snapshot.allocation_remaining_bytes()),(before,after));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 eprintln!("[DEBUG] genuine TransferSnapshot typed export preserves original native refusal, phase cancellation and independent Bun SQLite rows");
}
