  let payload=input(encoding);let file=run(&export_route,payload.clone(),limits(),&mut|_|true,&mut native).await.unwrap().value;let mut yes=|_|true;let mut direct=SqliteSnapshotControl::new(&mut yes,limits());let mut domain=Some(export(&payload,&mut SqliteSnapshotControl::new(&mut|_|true,limits()),&mut native.snapshot_decode().unwrap()).unwrap().value);assert_eq!(import(&mut domain,encoding,&mut direct,&mut native.snapshot_encode().unwrap()).unwrap().value,payload);let used=limits().max_allocation_bytes-direct.allocation_remaining_bytes();assert_eq!(used,neutral()["literal"].as_str().unwrap().len()*usize::try_from(neutral()["importCopies"].as_u64().unwrap()).unwrap());
