#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_whole_hop_original_route_refusals_preserve_caller_and_zero_authority(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🛂️route/🧫️fixtures/🔣️.json")).unwrap();let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(fixture["original"]["grant"].clone()).unwrap();let mut observations=Vec::new();
 for case in fixture["cases"].as_array().unwrap(){
  let coordinate=|value:&serde_json::Value|ArtifactDialect{artifact_kind:value["artifactKind"].as_str().unwrap().into(),standard:value["standard"].as_str().unwrap().into(),subset:value["subset"].as_str().unwrap().into()};let fidelity=match case["route"]["fidelity"].as_str().unwrap(){"Exact"=>IoFidelity::Exact,"Canonical"=>IoFidelity::Canonical,_=>unreachable!()};
  let route=IoRoute{hops:case["route"]["hops"].as_array().unwrap().iter().map(|hop|IoEntryDescriptor{from:coordinate(&hop["from"]),into:coordinate(&hop["into"]),fidelity:IoFidelity::Exact,sniffs:false}).collect(),fidelity};
  let mut input=Some(IoPayload::Text(fixture["original"]["inputText"].as_str().unwrap().into()));let pointer=match input.as_ref().unwrap(){IoPayload::Text(text)=>text.as_ptr(),_=>unreachable!()};let mut decode_observer=|_|true;let mut encode_observer=|_|true;let mut sql_observer=|_|true;let maximum=fixture["original"]["nativeMaximumBytes"].as_u64().unwrap()as usize;let mut decode=NativeDecodeControl::new(maximum,&mut decode_observer);let mut encode=NativeEncodeControl::new(maximum,&mut encode_observer);let mut original=IoRunControl::new(&mut decode,&mut encode,grant);let mut sql=SqliteSnapshotControl::new(&mut sql_observer,SqliteDatabaseLimits{max_allocation_bytes:0,..Default::default()});let sql_before=sql.allocation_remaining_bytes();
  let(ready,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||io_run_with_snapshot_control(&route,&mut input,&mut original,&mut sql));let result=ready.await;let error=result.unwrap_err();assert_eq!(error.cause.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.cause.message.as_ref(),case["cause"].as_str().unwrap());assert!(error.diagnostics.is_empty());
  let literal=matches!(error.cause.message,std::borrow::Cow::Borrowed(_));eprintln!("[DEBUG] Original OS route case={} actualBorn={} actualReleased={} borrowedCause={}",case["id"],heap.requested_bytes,heap.released_bytes,literal);observations.push((case,heap.requested_bytes,heap.released_bytes,literal));assert_eq!(original.progress(),Default::default());assert_eq!(error.cause.retained_progress(),Default::default());assert_eq!(sql.allocation_remaining_bytes(),sql_before);let IoPayload::Text(text)=input.as_ref().unwrap()else{unreachable!()};assert_eq!(text.as_ptr(),pointer);assert_eq!(text,fixture["original"]["inputText"].as_str().unwrap());drop(original);assert_eq!((decode.owned_bytes(),encode.owned_bytes()),(0,0));assert!(!decode.has_retirement_owner()&&!encode.has_retirement_owner());
 }
 for(case,born,released,literal)in observations{assert_eq!(born,case["allocatedBytes"].as_u64().unwrap()as usize,"{}",case["id"]);assert_eq!(released,case["releasedBytes"].as_u64().unwrap()as usize,"{}",case["id"]);assert!(literal,"{}",case["id"]);}
 eprintln!("[DEBUG] Original public OS route admission preserves caller payload pointer, literal refusal and zero original native/body/SQL/allocator effects for five independently checked route policies");
}
